const stockCostForUpdate = `-- name: StockCostForUpdate :one
SELECT id, avg_cost::text AS avg_cost, cost_currency,
       on_hand_qty::text AS on_hand_qty, total_cost::text AS total_cost
FROM stocks
WHERE tenant_id = $1::bigint AND id = $2::bigint
FOR UPDATE
`

type StockCostForUpdateParams struct {
	TenantID int64
	ID       int64
}

type StockCostForUpdateRow struct {
	ID           int64
	AvgCost      string
	CostCurrency string
	OnHandQty    string
	TotalCost    string
}

// The average this row currently carries, locked so a concurrent receipt
// cannot move it between the read and the movement priced against it.
func (q *Queries) StockCostForUpdate(ctx context.Context, arg StockCostForUpdateParams) (StockCostForUpdateRow, error) {
	row := q.db.QueryRow(ctx, stockCostForUpdate, arg.TenantID, arg.ID)
	var i StockCostForUpdateRow
	err := row.Scan(
		&i.ID,
		&i.AvgCost,
		&i.CostCurrency,
		&i.OnHandQty,
		&i.TotalCost,
	)
	return i, err
}

const stocksForItemForUpdate = `-- name: StocksForItemForUpdate :many
SELECT id, warehouse_id, available_qty::text AS available_qty
FROM stocks
WHERE tenant_id = $1
  AND product_id = $2
  AND sku_id = $3
  AND available_qty > 0
ORDER BY id
FOR UPDATE
`

type StocksForItemForUpdateParams struct {
	TenantID  int64
	ProductID int64
	SkuID     int64
}

type StocksForItemForUpdateRow struct {
	ID           int64
	WarehouseID  int64
	AvailableQty string
}

// Candidate rows to allocate from, locked in a stable order so two concurrent
// reservations for the same item queue instead of interleaving.
//
// Matched on product AND sku: sku_id 0 means the product has no variants, and
// keying on sku alone would make every such product look like the same thing.
func (q *Queries) StocksForItemForUpdate(ctx context.Context, arg StocksForItemForUpdateParams) ([]StocksForItemForUpdateRow, error) {
	rows, err := q.db.Query(ctx, stocksForItemForUpdate, arg.TenantID, arg.ProductID, arg.SkuID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StocksForItemForUpdateRow
	for rows.Next() {
		var i StocksForItemForUpdateRow
		if err := rows.Scan(&i.ID, &i.WarehouseID, &i.AvailableQty); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

