const upsertStockOnInbound = `-- name: UpsertStockOnInbound :one
INSERT INTO stocks (
    tenant_id, warehouse_id, product_id, sku_id, uom_id, uom_code,
    product_code, product_name, on_hand_qty, total_cost, cost_currency
) VALUES (
    $1::bigint,
    $2::bigint,
    $3::bigint,
    $4::bigint,
    $5::bigint,
    $6::text,
    $7::text,
    $8::text,
    $9::text::numeric,
    $10::text::numeric,
    $11::text
)
ON CONFLICT (tenant_id, warehouse_id, product_id, sku_id) DO UPDATE SET
    on_hand_qty  = stocks.on_hand_qty + excluded.on_hand_qty,
    total_cost   = stocks.total_cost + excluded.total_cost,
    product_code = excluded.product_code,
    product_name = excluded.product_name,
    updated_at   = now()
RETURNING id, on_hand_qty::text AS on_hand_qty, available_qty::text AS available_qty,
          avg_cost::text AS avg_cost, cost_currency
`

type UpsertStockOnInboundParams struct {
	TenantID     int64
	WarehouseID  int64
	ProductID    int64
	SkuID        int64
	UomID        int64
	UomCode      string
	ProductCode  string
	ProductName  string
	Qty          string
	Amount       string
	CostCurrency string
}

type UpsertStockOnInboundRow struct {
	ID           int64
	OnHandQty    string
	AvailableQty string
	AvgCost      string
	CostCurrency string
}

// Receiving goods. The row is created on first receipt of a SKU into a
// warehouse, so nothing has to pre-register a stock record.
//
// Cost rides along: quantity and value move together or the average is wrong
// from the next movement onwards. cost_currency is only set on creation —
// changing it later would reinterpret a pool of money already in the row.
func (q *Queries) UpsertStockOnInbound(ctx context.Context, arg UpsertStockOnInboundParams) (UpsertStockOnInboundRow, error) {
	row := q.db.QueryRow(ctx, upsertStockOnInbound,
		arg.TenantID,
		arg.WarehouseID,
		arg.ProductID,
		arg.SkuID,
		arg.UomID,
		arg.UomCode,
		arg.ProductCode,
		arg.ProductName,
		arg.Qty,
		arg.Amount,
		arg.CostCurrency,
	)
	var i UpsertStockOnInboundRow
	err := row.Scan(
		&i.ID,
		&i.OnHandQty,
		&i.AvailableQty,
		&i.AvgCost,
		&i.CostCurrency,
	)
	return i, err
}

const upsertWarehouseSettings = `-- name: UpsertWarehouseSettings :exec
INSERT INTO warehouse_settings (
    tenant_id, usage_mode, allow_direct_delivery, allow_inventory,
    default_warehouse_id, updated_by, updated_at
) VALUES (
    $1::bigint, $2::text,
    $3::bool, $4::bool,
    NULLIF($5::bigint, 0),
    NULLIF($6::bigint, 0), now()
)
ON CONFLICT (tenant_id) DO UPDATE SET
    usage_mode = excluded.usage_mode,
    allow_direct_delivery = excluded.allow_direct_delivery,
    allow_inventory = excluded.allow_inventory,
    default_warehouse_id = excluded.default_warehouse_id,
    updated_by = excluded.updated_by,
    updated_at = now()
`

type UpsertWarehouseSettingsParams struct {
	TenantID            int64
	UsageMode           string
	AllowDirectDelivery bool
	AllowInventory      bool
	DefaultWarehouseID  int64
	UpdatedBy           int64
}

func (q *Queries) UpsertWarehouseSettings(ctx context.Context, arg UpsertWarehouseSettingsParams) error {
	_, err := q.db.Exec(ctx, upsertWarehouseSettings,
		arg.TenantID,
		arg.UsageMode,
		arg.AllowDirectDelivery,
		arg.AllowInventory,
		arg.DefaultWarehouseID,
		arg.UpdatedBy,
	)
	return err
}
